import pandas as pd

def consecutive_available_seats_ii(cinema: pd.DataFrame) -> pd.DataFrame:
    free = cinema[cinema['free'] == 1].copy()
    if free.empty:
        return pd.DataFrame(columns=['first_seat_id', 'last_seat_id', 'consecutive_seats_len'])

    free = free.sort_values(by='seat_id')
    free['row_num'] = range(1, len(free) + 1)
    free['group_id'] = free['seat_id'] - free['row_num']

    grouped = free.groupby('group_id').agg(
        first_seat_id=('seat_id', 'min'),
        last_seat_id=('seat_id', 'max'),
        consecutive_seats_len=('seat_id', 'count')
    ).reset_index()

    max_len = grouped['consecutive_seats_len'].max()
    res = grouped[grouped['consecutive_seats_len'] == max_len]
    return res[['first_seat_id', 'last_seat_id', 'consecutive_seats_len']].sort_values(by='first_seat_id')
